                adj[i].push(j);
            }
        }
    }

    // Matrix exponentiation
    function matMult(a, b) {
        const res = Array.from({ length: a.length }, () => new Array(a.length).fill(0));
        for (let i = 0; i < a.length; i++) {
            for (let k = 0; k < a.length; k++) {
                if (a[i][k] === 0) continue;
                for (let j = 0; j < a.length; j++) {
                    res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD;
                }
            }
        }
        return res;
    }

    function matPow(mat, power) {
        let result = Array.from({ length: mat.length }, (_, i) => Array.from({ length: mat.length }, (_, j) => i === j ? 1 : 0));
        while (power > 0) {
            if (power % 2 === 1) {
                result = matMult(result, mat);
            }
            mat = matMult(mat, mat);
            power = Math.floor(power / 2);
        }
        return result;
    }

    // Initial vector: count of words of length 1
    const initial = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        if (words[i].length === 1) {
            initial[i] = 1;
        }
    }

    // Compute transition matrix raised to (m-1)
    const transMatrix = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (const j of adj[i]) {
            transMatrix[i][j] = 1;
        }
    }

    let finalMatrix;
    if (m === 1) {
        finalMatrix = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => i === j ? 1 : 0));
    } else {
        finalMatrix = matPow(transMatrix, m - 1);
    }

    // Multiply initial vector with finalMatrix
    const result = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            result[j] = (result[j] + initial[i] * finalMatrix[i][j]) % MOD;
        }
    }

    // Sum all possible end states
    let total = 0;
    for (let i = 0; i < n; i++) {
        total = (total + result[i]) % MOD;
    }

    console.log(total);
}

main();
